Consider the following C program:
<pre><code>
#include &lt;stdio.h&gt;

int main(){
    int a;
    int arr[5] = {30,50,10};
    int *ptr;
    ptr = &arr[0] + 1;
    a = *ptr;
    (*ptr)++;
    ptr++;
    printf("%d", a + (*ptr) + arr[1]);
    return 0;
}
</code></pre>
The output of the above program is ___________. (Answer in integer)

Consider the following C program:
<pre><code>
#include &lt;stdio.h&gt;

void stringcopy(char *, char *);

int main(){
    char a[30] = "@#Hello World!";
    stringcopy(a, a + 2);
    printf("%s\n", a);
    return 0;
}

void stringcopy(char *s, char *t) {
    while(*t)
        *s++ = *t++;
}
</code></pre>

Which ONE of the following will be the output of the program?

Consider the following C program:
<pre><code>
#include &lt;stdio.h&gt;  
int gate(int n) {  
    int d, t, newnum, turn;  
    newnum = turn = 0; t=1;  
    while(n >= t) t *= 10;  
    t /= 10;  
    while(t > 0) {  
        d = n / t;  
        n = n % t;  
        t /= 10;  
        if(turn) newnum = 10 * newnum + d;  
        turn = (turn + 1) % 2;  
    }  
    return newnum;  
}  
int main () {  
    printf("%d", gate(14362));  
    return 0;  
}
</code></pre>
The value printed by the given C program is _________. (Answer in integer)
